import { api } from "encore.dev/api";

export interface UserParams {
  id: number;
}

export interface UserResponse {
  id: number;
  name: string;
}

// Returns a user by ID. If the ID is 1, returns "Alice", otherwise "Unknown".
export const getUser = api<UserParams, UserResponse>(
  { method: "GET", path: "/user/:id" },
  async ({ id }) => {
    return {
      id,
      name: id === 1 ? "Alice" : "Unknown",
    };
  }
);

import { api } from "encore.dev/api";
import { user } from "~encore/clients";

export interface OrderParams {
  id: number;
}

export interface OrderResponse {
  orderId: number;
  userId: number;
  userName: string;
}

// Returns an order by ID. Always fetches user ID 1 from the user service.
export const getOrder = api<OrderParams, OrderResponse>(
  { method: "GET", path: "/order/:id" },
  async ({ id }) => {
    const u = await user.getUser({ id: 1 });
    return {
      orderId: id,
      userId: u.id,
      userName: u.name,
    };
  }
);

